import { Router, type IRouter, type Request, type Response, type NextFunction } from "express";
import crypto from "node:crypto";
import { and, asc, desc, eq, isNull, or, sql } from "drizzle-orm";
import {
  db,
  workspaces,
  workspaceMembers,
  projects,
  appUsers,
  entities,
  rules,
  players,
  notes,
  type Workspace,
} from "@workspace/db";
import {
  ensurePersonalWorkspace,
  findProjectInWorkspace,
  findWorkspaceBySlug,
  generateProjectSlug,
  isUniqueViolation,
  listUserWorkspaces,
  userHasWorkspaceAccess,
} from "../lib/workspaceHelpers";
import { ensureUniqueSlug } from "../lib/slug";
import { complete, tryParseJsonObject } from "../lib/aiRouter";
import {
  ALL_PROVIDERS,
  listWorkspaceProviderSettings,
  upsertWorkspaceProviderSettings,
  type WorkspaceProvider,
} from "../lib/workspaceAiSettings";

const router: IRouter = Router();

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Express {
    interface Request {
      workspace?: Workspace;
      workspaceRole?: string;
    }
  }
}

async function loadWorkspace(
  req: Request,
  res: Response,
  next: NextFunction,
): Promise<void> {
  const slug = String(req.params.workspaceSlug ?? "");
  if (!slug) {
    res.status(400).json({ error: "Missing workspace slug" });
    return;
  }
  const ws = await findWorkspaceBySlug(slug);
  if (!ws) {
    res.status(404).json({ error: "Workspace not found" });
    return;
  }
  if (!req.appUserId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
  const access = await userHasWorkspaceAccess(ws.id, req.appUserId);
  if (!access.access && req.appUserRole !== "admin") {
    res.status(403).json({ error: "Forbidden" });
    return;
  }
  req.workspace = ws;
  req.workspaceRole = access.role ?? (req.appUserRole === "admin" ? "admin" : null) ?? "viewer";
  next();
}

// GET /workspaces — list user's workspaces (ensures Personal exists)
function generateInviteCode(): string {
  return crypto.randomBytes(12).toString("hex");
}

// GET /workspaces/join/:code — preview a workspace by invite code (no auth required)
router.get("/workspaces/join/:code", async (req, res): Promise<void> => {
  const code = String(req.params.code ?? "").trim();
  if (!code) { res.status(400).json({ error: "Missing code" }); return; }
  const [ws] = await db.select().from(workspaces).where(eq(workspaces.inviteCode, code));
  if (!ws) { res.status(404).json({ error: "Invalid or expired invite link" }); return; }
  const [{ memberCount }] = await db
    .select({ memberCount: sql<number>`count(*)::int` })
    .from(workspaceMembers)
    .where(and(eq(workspaceMembers.workspaceId, ws.id), eq(workspaceMembers.status, "active")));
  res.json({ id: ws.id, name: ws.name, slug: ws.slug, memberCount });
});

// POST /workspaces/join/:code — join workspace via invite code (requires auth)
router.post("/workspaces/join/:code", async (req, res): Promise<void> => {
  if (!req.appUserId) { res.status(401).json({ error: "Unauthorized" }); return; }
  const code = String(req.params.code ?? "").trim();
  const [ws] = await db.select().from(workspaces).where(eq(workspaces.inviteCode, code));
  if (!ws) { res.status(404).json({ error: "Invalid or expired invite link" }); return; }
  await db
    .insert(workspaceMembers)
    .values({ workspaceId: ws.id, userId: req.appUserId, role: "member", status: "active", joinedAt: new Date() })
    .onConflictDoUpdate({
      target: [workspaceMembers.workspaceId, workspaceMembers.userId],
      set: { status: "active", joinedAt: new Date() },
    });
  res.json({ slug: ws.slug, name: ws.name });
});

// GET /workspaces — list user's workspaces (ensures Personal exists)
router.get("/workspaces", async (req, res): Promise<void> => {
  if (!req.appUserId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
  await ensurePersonalWorkspace(req.appUserId);
  const list = await listUserWorkspaces(req.appUserId);
  res.json(list);
});

// POST /workspaces — create workspace
router.post("/workspaces", async (req, res): Promise<void> => {
  if (!req.appUserId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
  const name = String(req.body?.name ?? "").trim();
  if (!name) {
    res.status(400).json({ error: "Name required" });
    return;
  }
  const baseSlug = String(req.body?.slug || name);
  let created: Workspace | undefined;
  let attempt = 0;
  while (attempt < 5 && !created) {
    attempt += 1;
    const slug = await ensureUniqueSlug(baseSlug, async (s) => {
      const [hit] = await db.select({ id: workspaces.id }).from(workspaces).where(eq(workspaces.slug, s));
      return Boolean(hit);
    });
    try {
      const rows = await db
        .insert(workspaces)
        .values({ slug, name, ownerUserId: req.appUserId, isPersonal: 0 })
        .returning();
      created = rows[0];
    } catch (err) {
      if (!isUniqueViolation(err)) throw err;
      // raced — loop with a fresh slug
    }
  }
  if (!created) {
    res.status(500).json({ error: "Could not allocate workspace slug" });
    return;
  }
  await db
    .insert(workspaceMembers)
    .values({
      workspaceId: created.id,
      userId: req.appUserId,
      role: "owner",
      status: "active",
      joinedAt: new Date(),
    })
    .onConflictDoNothing();
  res.status(201).json(created);
});

// GET /workspaces/:slug — workspace + projects + members
router.get("/workspaces/:workspaceSlug", loadWorkspace, async (req, res): Promise<void> => {
  const ws = req.workspace!;
  const projs = await db
    .select()
    .from(projects)
    .where(and(eq(projects.workspaceId, ws.id), isNull(projects.deletedAt)))
    .orderBy(desc(projects.updatedAt));
  const memberRows = await db
    .select({
      m: workspaceMembers,
      u: appUsers,
    })
    .from(workspaceMembers)
    .leftJoin(appUsers, eq(workspaceMembers.userId, appUsers.id))
    .where(eq(workspaceMembers.workspaceId, ws.id))
    .orderBy(asc(workspaceMembers.createdAt));
  const members = memberRows.map((r) => ({
    id: r.m.id,
    role: r.m.role,
    status: r.m.status,
    invitedEmail: r.m.invitedEmail,
    user: r.u
      ? {
          id: r.u.id,
          email: r.u.email,
          firstName: r.u.firstName,
          lastName: r.u.lastName,
          imageUrl: r.u.imageUrl,
        }
      : null,
    joinedAt: r.m.joinedAt,
    invitedAt: r.m.invitedAt,
  }));
  res.json({
    workspace: ws,
    role: req.workspaceRole,
    projects: projs,
    members,
  });
});

// GET /workspaces/:slug/invite-code — get (or lazily create) invite code
router.get(
  "/workspaces/:workspaceSlug/invite-code",
  loadWorkspace,
  async (req, res): Promise<void> => {
    if (!["owner", "admin"].includes(req.workspaceRole ?? "") && req.appUserRole !== "admin") {
      res.status(403).json({ error: "Forbidden" });
      return;
    }
    let ws = req.workspace!;
    if (!ws.inviteCode) {
      const [updated] = await db
        .update(workspaces)
        .set({ inviteCode: generateInviteCode() })
        .where(eq(workspaces.id, ws.id))
        .returning();
      ws = updated;
    }
    const origin = `${req.protocol}://${req.get("host")}`;
    res.json({ inviteCode: ws.inviteCode, joinUrl: `${origin}/join/${ws.inviteCode}` });
  },
);

// POST /workspaces/:slug/invite-code/refresh — regenerate invite code (invalidates old link)
router.post(
  "/workspaces/:workspaceSlug/invite-code/refresh",
  loadWorkspace,
  async (req, res): Promise<void> => {
